-- Phase 45: incident post-mortem and lessons-learned register
create table if not exists public.election_incident_postmortems(id uuid primary key default gen_random_uuid(),award_space_id uuid not null references public.award_spaces(id) on delete cascade,incident_id uuid not null unique references public.election_incidents(id) on delete cascade,root_cause text not null,impact_summary text not null,response_assessment text not null,lessons_learned text not null,preventive_actions text not null,owner_id uuid references public.admins(id) on delete set null,target_date date,status text not null default 'open' check(status in('open','in_progress','completed','accepted')),created_by uuid references public.admins(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),completed_at timestamptz,accepted_at timestamptz,accepted_by uuid references public.admins(id) on delete set null);
create index if not exists election_incident_postmortems_space_idx on public.election_incident_postmortems(award_space_id,status,target_date);
alter table public.election_incident_postmortems enable row level security;
